<?php
require_once __DIR__ . '/includes/bootstrap.php';
adminRequireLogin(); ensureOrderManagementTables(); ensureOrderPaymentsTable(); ensureMisTables();
$conn = adminDb();
$counts = array('foods'=>0,'orders'=>0,'customers'=>0,'messages'=>0,'blog_posts'=>0);
if ($conn) foreach ($counts as $table => &$count) { $result = mysqli_query($conn, 'SELECT COUNT(*) total FROM ' . $table); if ($result) $count = (int)(mysqli_fetch_assoc($result)['total'] ?? 0); } unset($count);
$queueRows = adminRows("SELECT COALESCE(t.status,'placed') status,COUNT(*) total FROM orders o LEFT JOIN order_tracking t ON t.orderid=o.orderid GROUP BY COALESCE(t.status,'placed')");
$queues = array_fill_keys(array('placed','payment_pending','confirmed','preparing','ready_for_pickup','rider_assigned','out_for_delivery','delivered','completed','cancelled'), 0);
foreach ($queueRows as $queue) $queues[$queue['status']] = (int)$queue['total'];
$recent = adminRows("SELECT o.orderid,o.name,f.total_amount,COALESCE(t.status,'placed') status,t.updated_at FROM orders o LEFT JOIN order_financials f ON f.orderid=o.orderid LEFT JOIN order_tracking t ON t.orderid=o.orderid ORDER BY o.orderid DESC LIMIT 6");
$finance = adminRows("SELECT COALESCE(SUM(CASE WHEN COALESCE(t.status,'placed') <> 'cancelled' THEN f.total_amount ELSE 0 END),0) revenue,COALESCE(SUM(f.discount_amount),0) discounts,COALESCE(SUM(r.amount),0) refunds FROM orders o LEFT JOIN order_financials f ON f.orderid=o.orderid LEFT JOIN order_tracking t ON t.orderid=o.orderid LEFT JOIN order_refunds r ON r.orderid=o.orderid");
$finance = $finance[0] ?? array('revenue'=>0,'discounts'=>0,'refunds'=>0);
$attention = adminRows("SELECT (SELECT COUNT(*) FROM order_cancellations WHERE status='requested') cancellations,(SELECT COUNT(*) FROM order_item_cancellations WHERE status='requested') item_cancellations,(SELECT COUNT(*) FROM order_refunds WHERE status IN ('requested','approved','processing')) refunds,(SELECT COUNT(*) FROM support_tickets WHERE status IN ('open','in_progress','waiting_for_customer')) tickets");
$attention = $attention[0] ?? array('cancellations'=>0,'item_cancellations'=>0,'refunds'=>0,'tickets'=>0);
$adminTitle='Dashboard'; $adminPage='home'; $adminStyles=array('dashboard.css'); include __DIR__ . '/includes/header.php';
?>
<section class="dashboard-hero"><div><p>Operations overview</p><h2>Today at Foodera</h2><span>Monitor incoming orders, kitchen flow, deliveries, and customer requests from one place.</span></div><div class="dashboard-hero-actions"><a class="admin-btn" href="order-details.php"><i class="bi bi-bag-check"></i> Manage orders</a><a class="admin-btn secondary" href="operations.php"><i class="bi bi-truck"></i> Delivery desk</a></div></section>
<section class="dashboard-metrics" aria-label="Store metrics"><?php foreach(array('foods'=>array('Menu items','bi-cup-hot','menu.php'),'orders'=>array('Orders','bi-bag','order-details.php'),'customers'=>array('Customers','bi-people','customer-details.php'),'messages'=>array('Messages','bi-envelope','message.php'),'blog_posts'=>array('Stories','bi-journal-text','blog.php')) as $key=>$item){ ?><a href="<?php echo $item[2]; ?>"><i class="bi <?php echo $item[1]; ?>"></i><span><?php echo $item[0]; ?></span><strong><?php echo $counts[$key]; ?></strong><small>Open <?php echo strtolower($item[0]); ?> <i class="bi bi-arrow-right"></i></small></a><?php } ?></section>
<section class="admin-card dashboard-section"><div class="admin-toolbar"><div><h2>Order workflow</h2><p class="admin-muted">Live order workload by the current operating stage.</p></div><a class="admin-btn secondary" href="order-details.php">All orders <i class="bi bi-arrow-right"></i></a></div><div class="dashboard-queue-grid"><?php foreach(array('placed'=>array('New orders','bi-receipt'),'confirmed'=>array('Confirmed','bi-patch-check'),'preparing'=>array('Preparing','bi-fire'),'ready_for_pickup'=>array('Ready for pickup','bi-bag-check'),'rider_assigned'=>array('Rider assigned','bi-person-check'),'out_for_delivery'=>array('On delivery','bi-truck')) as $status=>$item){ ?><a href="order-details.php?status=<?php echo $status; ?>"><i class="bi <?php echo $item[1]; ?>"></i><span><?php echo $item[0]; ?></span><strong><?php echo $queues[$status]; ?></strong></a><?php } ?></div></section>
<section class="dashboard-split"><section class="admin-card dashboard-section"><div class="admin-toolbar"><div><h2>Needs attention</h2><p class="admin-muted">Requests needing an admin decision or follow-up.</p></div></div><div class="dashboard-attention"><a href="order-details.php#cancellations"><i class="bi bi-x-circle"></i><div><strong><?php echo (int)$attention['cancellations']; ?></strong><span>Order cancellations</span></div><i class="bi bi-chevron-right"></i></a><a href="order-details.php#dish-cancellations"><i class="bi bi-bag-x"></i><div><strong><?php echo (int)$attention['item_cancellations']; ?></strong><span>Dish cancellations</span></div><i class="bi bi-chevron-right"></i></a><a href="order-details.php#refunds"><i class="bi bi-arrow-counterclockwise"></i><div><strong><?php echo (int)$attention['refunds']; ?></strong><span>Refunds in progress</span></div><i class="bi bi-chevron-right"></i></a><a href="support.php"><i class="bi bi-life-preserver"></i><div><strong><?php echo (int)$attention['tickets']; ?></strong><span>Open support tickets</span></div><i class="bi bi-chevron-right"></i></a></div></section><section class="admin-card dashboard-section"><div class="admin-toolbar"><div><h2>Financial snapshot</h2><p class="admin-muted">Live value after discounts and recorded refunds.</p></div><a class="admin-btn secondary" href="reports.php">Reports <i class="bi bi-bar-chart-line"></i></a></div><div class="dashboard-finance"><div><span>Order revenue</span><strong>Rs <?php echo number_format((float)$finance['revenue']); ?></strong></div><div><span>Discounts</span><strong>Rs <?php echo number_format((float)$finance['discounts']); ?></strong></div><div><span>Refund value</span><strong>Rs <?php echo number_format((float)$finance['refunds']); ?></strong></div></div></section></section>
<section class="admin-card dashboard-section"><div class="admin-toolbar"><div><h2>Recent orders</h2><p class="admin-muted">The latest customer orders and their current stage.</p></div><a class="admin-btn secondary" href="order-details.php">View all</a></div><div class="admin-table-wrap"><table class="admin-table dashboard-orders"><thead><tr><th>Order</th><th>Customer</th><th>Current stage</th><th>Total</th><th>Updated</th></tr></thead><tbody><?php foreach($recent as $row){ ?><tr><td><a href="order-details.php?order=<?php echo (int)$row['orderid']; ?>">#<?php echo (int)$row['orderid']; ?></a></td><td><?php echo adminEscape($row['name']); ?></td><td><span class="admin-badge live"><?php echo adminEscape(ucwords(str_replace('_',' ',$row['status']))); ?></span></td><td><strong>Rs <?php echo number_format((float)$row['total_amount']); ?></strong></td><td><?php echo adminEscape(date('d M, h:i A',strtotime($row['updated_at'] ?? 'now'))); ?></td></tr><?php } ?></tbody></table><?php if(!$recent){ ?><p class="admin-muted">No orders yet.</p><?php } ?></div></section>
